using System;using System.IO;using SargasPC;
class StartupTests{static int n;static void Check(bool b){if(!b)throw new Exception("Startup check "+n);n++;}static void Reject(string p){bool hit=false;try{Window.StartupCommand(p);}catch(IOException){hit=true;}Check(hit);}static void Main(){Reject(null);Reject("");Reject("relative.exe");Reject("/tmp/a\"b.exe");Reject("/tmp/a\nb.exe");string root=Path.Combine(Path.GetTempPath(),"startup-"+Guid.NewGuid());Directory.CreateDirectory(root);try{Check(Window.StartupCommand(Path.Combine(root,"app space.exe"))=="\""+Path.Combine(root,"app space.exe")+"\" --startup");string sub=Path.Combine(root,"nested");Directory.CreateDirectory(sub);File.WriteAllText(Path.Combine(sub,"not-enqueued.txt"),"sub");for(int i=0;i<130;i++)File.WriteAllText(Path.Combine(root,i+".txt"),"safe");using(var m=new FolderMonitor(root,false)){m.SeedExisting();Check(m.Count==128);Check(m.Dropped>0);string p=m.Take(DateTime.UtcNow.AddSeconds(6).Ticks);Check(p!=null&&Path.GetDirectoryName(p)==root);Check(m.Count==127);m.Enqueue(Path.Combine(sub,"not-enqueued.txt"),0);Check(m.Count==127);}Console.WriteLine("PASS: "+n+" startup/initial-queue checks; registry and reboot not tested on Windows.");}finally{Directory.Delete(root,true);}}}
